// Stub methods for WorldTick compatibility
    public getActiveChunks(): any[] {
        return Array.from(this.chunks.values()).filter((c: any) => c && c.isActive);
    }

    public setChunkActive(id: string, active: boolean): void {
        const [x, y] = id.split(':').map(Number);
        const chunk = this.getChunk(x, y);
        if (chunk) {
            (chunk as any).isActive = active;
        }
    }

